/bin/zsh -lc "python analysis.py | python -c 'import sys,json; x=json.load(sys.stdin); print(\"json ok\", x[\"n\"], len(x[\"fitted\"]), type(next(iter(x[\"fitted\"]))))' && python -c 'import pandas as pd; from analysis import fit_quadratic_trend; d=pd.DataFrame({\"year\":[2000,2001,2002],\"latitude\":[1,1,1],\"longitude\":[2,2,2],\"air_temperature\":[3.,4.,5.]});
for lat,lon in [(9,2),(1,2)]:
 try: fit_quadratic_trend(d,lat,lon)
 except ValueError as e: print(\"ValueError ok\", lat, str(e))' && git diff -- analysis.py"

